export type ArrowSquareUpIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ArrowSquareUpIcon({ size = 20, ...props }: ArrowSquareUpIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="16" rx="2" /><path d="M12 16v-7M8.5 11.5 12 8l3.5 3.5" />
